    // ── PC makeup board (PC_MAKEUP_PHASE2_GRADE_SPEC.md §E) ──────────────────
    // The unlock/block board + the two unlock actions. Consumes the class-scoped
    // GET /pc/unlock/class (NOT the caller-scoped /pc/unlock/status). Present-
    // student usernames come from the already-loaded /class/grades payload.
    function _pcNameMap() {
      var m = {};
      var students = (lastGradesPayload && lastGradesPayload.students) || [];
      students.forEach(function (s) { if (s && s.username) m[s.username] = s.realName || s.username; });
      return m;
    }

    function _pcPartLabel(part) {
      return String(part).toUpperCase() === 'A' ? 'MCQ Part A' : 'Rest (B/C + FRQ)';
    }

    function renderPcMakeup(payload) {
      var tbody = $('pc-makeup-tbody');
      var rows = (payload && payload.unlocks) || [];
      if (rows.length === 0) {
        $('pc-makeup-wrap').style.display = 'none';
        $('pc-makeup-empty').style.display = '';
        return;
      }
      $('pc-makeup-empty').style.display = 'none';
      $('pc-makeup-wrap').style.display = '';
      var names = _pcNameMap();
      var sorted = rows.slice().sort(function (a, b) {
        return (Number(a.unit) - Number(b.unit)) ||
          String(a.part).localeCompare(String(b.part)) ||
          String(names[a.student_username] || a.student_username || '').localeCompare(String(names[b.student_username] || b.student_username || ''));
      });
      tbody.innerHTML = sorted.map(function (r) {
        var uname = r.student_username || '';
        var name = names[uname] || uname || '?';
        return '<tr>' +
          '<td>' + escHtml(name) + '</td>' +
          '<td class="mono">U' + escHtml(r.unit) + '</td>' +
          '<td>' + escHtml(_pcPartLabel(r.part)) + '</td>' +
          '<td class="dim">' + escHtml(r.unlocked_by || '—') + '</td>' +
          '<td class="dim">' + escHtml(fmtDate(r.unlocked_at)) + '</td>' +
          '</tr>';
      }).join('');
    }

    async function loadPcMakeup() {
      var secret = teacherSecret();
      var _hasTok = (typeof window !== 'undefined' && window.rosterClient) ? !!window.rosterClient.token() : false;
      if (!secret && !_hasTok) return;
      $('pc-makeup-loading').style.display = '';
      $('pc-makeup-wrap').style.display = 'none';
      $('pc-makeup-empty').style.display = 'none';
      var res = await fetchJson('/pc/unlock/class', secret);
      $('pc-makeup-loading').style.display = 'none';
      if (res.networkError) { $('pc-makeup-meta').textContent = 'Network error: ' + res.networkError; return; }
      if (res.status === 503) {
        $('pc-makeup-empty').style.display = '';
        $('pc-makeup-meta').textContent = 'Migration pending: run roster-server/migrations/0029_pc_makeup.sql to enable.';
        return;
      }
      if (res.status === 401) { showError('Invalid teacher secret'); return; }
      if (res.status !== 200 || !res.data || !res.data.ok) {
        $('pc-makeup-meta').textContent = 'Failed to load /pc/unlock/class: ' + ((res.data && res.data.error) || ('HTTP ' + res.status));
        return;
      }
      renderPcMakeup(res.data);
      $('pc-makeup-meta').textContent = (res.data.unlocks || []).length + ' active unlock(s).';
    }

    function _pcUnitPart() {
      return { unit: parseInt($('pc-unit').value, 10), part: $('pc-part').value };
    }

    function _pcAuthOk() {
      var secret = teacherSecret();
      var _hasTok = (typeof window !== 'undefined' && window.rosterClient) ? !!window.rosterClient.token() : false;
      if (!secret && !_hasTok) { showError('Enter the teacher secret, or sign in as a teacher via the Desk first.'); return false; }
      return true;
    }

    async function unlockPcClass() {
      if (!_pcAuthOk()) return;
      var students = (lastGradesPayload && lastGradesPayload.students) || [];
      var usernames = students.map(function (s) { return s && s.username; }).filter(Boolean);
      if (usernames.length === 0) { showError('Load the gradebook first so the class roster is available.'); return; }
      var up = _pcUnitPart();
      var btn = $('pc-unlock-class-btn'); btn.disabled = true;
      var res = await postJson('/pc/unlock', { studentUsernames: usernames, unit: up.unit, part: up.part }, teacherSecret());
      btn.disabled = false;
      if (res.status === 503) { showError('Migration pending: run 0029_pc_makeup.sql.'); return; }
      if (res.status !== 200 || !res.data || !res.data.ok) { showError('unlock failed: ' + ((res.data && res.data.error) || ('HTTP ' + res.status))); return; }
      clearBanners();
      showInfo('Unlocked ' + (res.data.unlocked != null ? res.data.unlocked : usernames.length) + ' student(s) for U' + up.unit + ' ' + up.part + '. Leave absentees locked — unlock them individually after their paper makeup.');
      await loadPcMakeup();
    }

    async function unlockPcOne() {
      if (!_pcAuthOk()) return;
      var uname = $('pc-unlock-username').value.trim();
      if (!uname) { showError('Enter a username to unlock.'); return; }
      var up = _pcUnitPart();
      var btn = $('pc-unlock-one-btn'); btn.disabled = true;
      var res = await postJson('/pc/unlock/student', { studentUsername: uname, unit: up.unit, part: up.part }, teacherSecret());
      btn.disabled = false;
      if (res.status === 503) { showError('Migration pending: run 0029_pc_makeup.sql.'); return; }
      if (res.status !== 200 || !res.data || !res.data.ok) { showError('unlock failed: ' + ((res.data && res.data.error) || ('HTTP ' + res.status))); return; }
      clearBanners();
      showInfo('Unlocked ' + uname + ' for U' + up.unit + ' ' + up.part + '.');
      $('pc-unlock-username').value = '';
      await loadPcMakeup();
    }

    // Delegated click handler for action buttons in the remediation table.
    document.body.addEventListener('click', function (e) {
      var t = e.target;
      if (t && t.tagName === 'BUTTON' && t.getAttribute('data-act') && t.closest && t.closest('#remediation-tbody')) {
        handleRemediationAction(t);
      }
    });

    $('propose-from-mastery-btn').addEventListener('click', function () { handleProposeFromMastery(false); });
    $('propose-dryrun-btn').addEventListener('click', function () { handleProposeFromMastery(true); });
    // Codex Phase-4b MINOR-1: explicit panel-level Refresh affordance, plus
    // refresh-on-section-change so the table follows the active section
    // filter without requiring a full Load round-trip.
    $('remediation-refresh-btn').addEventListener('click', loadRemediation);
    $('section-filter').addEventListener('change', loadRemediation);

    // PC makeup board — same Load/Refresh/section triggers (parallel listeners).
    $('pc-makeup-refresh-btn').addEventListener('click', loadPcMakeup);
    $('pc-unlock-class-btn').addEventListener('click', unlockPcClass);
    $('pc-unlock-one-btn').addEventListener('click', unlockPcOne);
    $('load-btn').addEventListener('click', loadPcMakeup);
    $('section-filter').addEventListener('change', loadPcMakeup);

    // ── Quarter Close & Bonus (PC makeup [D] freeze/delta) ───────────────────
    function _qcQuarter() { return $('qc-quarter').value; }

    async function freezeQuarter() {
      if (!_pcAuthOk()) return;
      var q = _qcQuarter();
      var section = $('section-filter').value.trim();
      if (!confirm('Freeze ' + q + ' for ' + (section || 'ALL sections') + '?\n\nThis snapshots every student\'s CURRENT grade as the closed-quarter record. The first freeze wins — it cannot be undone here.')) return;
      var btn = $('qc-freeze-btn'); btn.disabled = true; $('qc-loading').style.display = '';
      var res = await postJson('/class/quarter/close', { quarter: q, section: section || undefined }, teacherSecret());
      btn.disabled = false; $('qc-loading').style.display = 'none';
      if (res.status === 503) { showError('Migration pending: run roster-server/migrations/0030_quarter_grade_snapshot.sql.'); return; }
      if (res.status !== 200 || !res.data || !res.data.ok) { showError('Freeze failed: ' + ((res.data && res.data.error) || ('HTTP ' + res.status))); return; }
      clearBanners();
      showInfo('Froze ' + q + ': ' + res.data.frozen + ' newly frozen of ' + res.data.considered + ' student(s).');
      await loadQuarterDeltas();
    }

    function renderQuarterDeltas(payload) {
      var tbody = $('qc-tbody');
      var rows = (payload && payload.deltas) || [];
      if (rows.length === 0) { $('qc-wrap').style.display = 'none'; $('qc-empty').style.display = ''; return; }
      $('qc-empty').style.display = 'none'; $('qc-wrap').style.display = '';
      tbody.innerHTML = rows.map(function (r) {
        return '<tr>' +
          '<td>' + escHtml(r.realName || r.username || '?') + '</td>' +
          '<td class="mono">' + escHtml(r.frozen) + '</td>' +
          '<td class="mono">' + escHtml(r.current) + '</td>' +
          '<td class="mono" style="color:#070;font-weight:bold">+' + escHtml(r.delta) + '</td>' +
          '</tr>';
      }).join('');
    }

    async function loadQuarterDeltas() {
      var secret = teacherSecret();
      var _hasTok = (typeof window !== 'undefined' && window.rosterClient) ? !!window.rosterClient.token() : false;
      if (!secret && !_hasTok) return;
      var q = _qcQuarter();
      var section = $('section-filter').value.trim();
      var qs = '?quarter=' + encodeURIComponent(q) + (section ? '&section=' + encodeURIComponent(section) : '');
      $('qc-loading').style.display = ''; $('qc-wrap').style.display = 'none'; $('qc-empty').style.display = 'none';
      var res = await fetchJson('/class/quarter/deltas' + qs, secret);
      $('qc-loading').style.display = 'none';
      if (res.networkError) { $('qc-meta').textContent = 'Network error: ' + res.networkError; return; }
      if (res.status === 503) { $('qc-empty').style.display = ''; $('qc-meta').textContent = 'Migration pending: run 0030_quarter_grade_snapshot.sql.'; return; }
      if (res.status === 401) { showError('Invalid teacher secret'); return; }
      if (res.status !== 200 || !res.data || !res.data.ok) { $('qc-meta').textContent = 'Failed: ' + ((res.data && res.data.error) || ('HTTP ' + res.status)); return; }
      renderQuarterDeltas(res.data);
      $('qc-meta').textContent = (res.data.deltas || []).length + ' bonus delta(s) · ' + (res.data.frozenCount || 0) + ' frozen.';
    }

    $('qc-freeze-btn').addEventListener('click', freezeQuarter);
    $('qc-deltas-btn').addEventListener('click', loadQuarterDeltas);
    $('qc-quarter').addEventListener('change', loadQuarterDeltas);

    // Hook remediation refresh onto the same Load triggers (parallel
    // listeners — the existing loadAll handler is left untouched).
    $('load-btn').addEventListener('click', loadRemediation);
    $('teacher-secret').addEventListener('keydown', function (e) {
      if (e.key === 'Enter') loadRemediation();
    });
    $('section-filter').addEventListener('keydown', function (e) {
      if (e.key === 'Enter') loadRemediation();
    });

    // ===== Teacher -> Student Console (TSC) drawer =====

    function teacherAuthHeaders() {
      // Codex MAJOR fold: forward BOTH credentials when present so a teacher
      // signed in via rosterClient (Bearer token) isn't forced to also type
      // the break-glass secret. requireTeacher checks header A first; if A is
      // present-but-wrong it falls through to Path B (token), so sending both
      // is safe.
      var headers = {};
      var sec = teacherSecret();
      if (sec) headers['x-teacher-secret'] = sec;
      var token = (window.rosterClient && typeof window.rosterClient.token === 'function')
        ? window.rosterClient.token() : null;
      if (token) headers['Authorization'] = 'Bearer ' + token;
      return headers;
    }

    function jsonOrErr(res) {
      if (!res.ok) return res.json().then(function(j) { throw new Error(j && j.error ? j.error : res.statusText); });
      return res.json();
    }

    function renderTscGrade(payload) {
      var el = $('tsc-grade-card');
      if (!payload || !payload.ok) { el.textContent = 'No grade data.'; return; }
      var q = (payload.quarters && payload.quarters.Q4) || (payload.quarters && Object.values(payload.quarters).find(Boolean));
      var html = [];
      if (q) {
        html.push('<div><strong>Current quarter:</strong> ' + escHtml(fmt1(q.quarterGrade)) +
                  (q.ceiling != null ? ' &uarr; ' + escHtml(fmt1(q.ceiling)) : '') + '</div>');
      }
      // Per-unit grades
      var units = payload.units || {};
      var unitLine = Object.keys(units).sort().map(function(k) {
        return k + ': ' + fmt1(units[k] && units[k].unitGrade);
      }).join(' &nbsp; ');
      if (unitLine) html.push('<div class="dim" style="font-size:0.82rem">' + unitLine + '</div>');
      el.innerHTML = html.join('');
    }

    // Phase 4: per-student "why do Schoology and v3 differ" breakdown. Reads the
    // reconciliation the deriver already attached to the loaded /class/grades
    // payload (no extra fetch) for the gradebook's current quarter.
    function _findStudentInLastPayload(studentId) {
      var students = (lastGradesPayload && lastGradesPayload.students) || [];
      for (var i = 0; i < students.length; i++) {
        if (String(students[i].studentId) === String(studentId)) return students[i];
      }
      return null;
    }

    function renderTscReconcile(studentId) {
      var el = $('tsc-reconcile-card');
      if (!el) return;
      var s = _findStudentInLastPayload(studentId);
      var gb = s && s.gradebook;
      var q = gb && gb.quarters && gb.quarters[currentQuarter];
      if (!q || !q.reconciliation) {
        el.innerHTML = '<span class="dim">No gradebook data for ' + escHtml(currentQuarter) + '.</span>';
        return;
      }
      var rc = q.reconciliation;
      var ca = q.categoryAverages || {};
      function n(x) { return x == null ? '&mdash;' : escHtml(fmt1(x)); }

      var deltaTxt = (rc.delta == null) ? '' : ((rc.delta > 0 ? '+' : '') + fmt1(rc.delta));
      var deltaCls = (rc.delta == null || Math.abs(rc.delta) < 0.1) ? '' : (rc.delta > 0 ? 'gb-good' : 'gb-low');

      var html = '';
      html += '<div><strong>' + escHtml(currentQuarter) + '</strong> &nbsp; PC track ' + n(rc.pcAvg) +
              ' &middot; Work track ' + n(rc.workAvg) + '</div>';
      html += '<div>v3: <strong>' + n(rc.v3Total) + '</strong> &nbsp; Schoology: <strong>' + n(rc.schoologyTotal) + '</strong>' +
              (deltaTxt ? ' &nbsp; <span class="' + deltaCls + '">&Delta; ' + escHtml(deltaTxt) + '</span>' : '') + '</div>';
      html += '<div class="dim" style="font-size:0.82rem">' + escHtml(rc.reason) + '</div>';

      var catOrder = ['Lesson', 'Quizzes', 'Blooket', 'Progress Check', 'Posters'];
      var catBits = catOrder.filter(function (c) { return ca[c] != null; })
        .map(function (c) { return c + ' ' + fmt1(ca[c]); });
      if (catBits.length) {
        html += '<div class="dim" style="font-size:0.8rem">Schoology categories (blank-excluded): ' + escHtml(catBits.join(' · ')) + '</div>';
      }

      // v3 Work-track sub-breakdown: the ACTUAL v3 inputs (due-denominator, missing
      // = 0), so you can compare them to the Schoology categories above and see
      // where v3 is harsher. Shows quiz/blooket "taken/due" so the #2 fix (quiz-
      // bearing denominator) is verifiable on a real student.
      var sq = s.quarters && s.quarters[currentQuarter];
      var wt = sq && sq.workTracks;
      if (wt) {
        var wtBits = [];
        if (wt.lessons != null) wtBits.push('Lessons ' + fmt1(wt.lessons));
        if (wt.quizzes != null) {
          wtBits.push('Quizzes ' + fmt1(wt.quizzes) +
            (sq.quizDue ? ' (' + (sq.quizDone || 0) + '/' + sq.quizDue + ' taken)' : ''));
        }
        if (wt.blooket != null) {
          wtBits.push('Blooket ' + fmt1(wt.blooket) +
            (sq.blooketDue ? ' (' + (sq.blooketDone || 0) + '/' + sq.blooketDue + ')' : ''));
        }
        if (wtBits.length) {
          html += '<div class="dim" style="font-size:0.8rem">v3 Work track (due-denominator, missing=0): ' +
            escHtml(wtBits.join(' · ')) + '</div>';
        }
      }
      el.innerHTML = html;
    }

    function renderTscRecent(payload) {
      var el = $('tsc-recent-list');
      el.innerHTML = '';
      if (!payload || !payload.ok) {
        el.innerHTML = '<li class="dim">No recent submissions.</li>';
        return;
      }
      var items = payload.submissions || [];
      if (items.length === 0) {
        el.innerHTML = '<li class="dim">No recent submissions.</li>';
        return;
      }
      items.forEach(function(row) {
        var li = document.createElement('li');
        var when = document.createElement('span');
        when.className = 'dim mono';
        when.style.fontSize = '0.78rem';
        when.textContent = (row.recordedAt || '').slice(0, 10);
        var what = document.createElement('span');
        what.textContent = (row.itemId || '') + ' · ' + (row.source || '');
        var score = document.createElement('span');
        score.className = 'dim mono';
        score.textContent = row.score == null ? '-' : String(row.score);
        li.appendChild(when); li.appendChild(what); li.appendChild(score);
        el.appendChild(li);
      });
    }

    // Codex MAJOR fold: per-open request sequence number. Each open bumps
    // _tscReqSeq; in-flight fetches verify they're still the active request
    // before rendering. closeTscDrawer also bumps so a late response after
    // close is dropped.
    var _tscReqSeq = 0;

    // P2: stash the studentId of the currently-open drawer so the View-as
    // button click handler (wired once at script-eval) can read it.
    var _tscCurrentStudentId = null;

    // P6 section 4: full stub of the currently-open drawer (sibling to
    // _tscCurrentStudentId from P1). Populated by openTscDrawer.
    var _tscCurrentStudentStub = null;

    // P12: pagination state for the Nudge History drawer section.
    //   _tscNudgeHistoryOffset = number of rows already loaded for the
    //     currently-open student. Reset to 0 on each openTscDrawer.
    //   _tscNudgeHistoryStudentUsername = the username this offset
    //     belongs to. Set on each openTscDrawer so a stale "Older" click
    //     from a prior drawer can't query the new student.
    //   _tscNudgeHistoryLoading = true while a fetch is in flight.
    var _tscNudgeHistoryOffset = 0;
    var _tscNudgeHistoryStudentUsername = null;
    var _tscNudgeHistoryLoading = false;
    var TSC_NUDGE_PAGE_SIZE = 20;

    function openTscDrawer(stub) {
      var drawer = $('tsc-drawer');
      if (!drawer) return;

      var reqId = ++_tscReqSeq;
      _tscCurrentStudentId = stub && stub.studentId ? stub.studentId : null;
      _tscCurrentStudentStub = stub || null;

      // P12: reset nudge pagination state and hide the "Older" button for this new open.
      _tscNudgeHistoryOffset = 0;
      _tscNudgeHistoryStudentUsername = stub && stub.username ? stub.username : null;
      _tscNudgeHistoryLoading = false;
      var _olderBtnReset = $('tsc-nudges-older');
      // Codex P12 BLOCKER fold: also restore the button text in case a
      // stale in-flight older fetch left it on "Loading..." when the
      // teacher switched students.
      if (_olderBtnReset) {
        _olderBtnReset.style.display = 'none';
        _olderBtnReset.disabled = false;
        _olderBtnReset.textContent = 'Load older';
      }

      // Populate header from the stub immediately so the user sees something.
      $('tsc-drawer-title').textContent = stub.realName || stub.username || 'Student';
      $('tsc-drawer-subtitle').textContent =
        (stub.username ? '@' + stub.username : '') +
        (stub.section ? ' -- ' + stub.section : '');

      // Body: loading state. Codex P6 MAJOR fold: clear unlocks-list too so
      // stale rows from a prior student do not linger between the open and
      // the resolution of the /lesson-unlocks fetch.
      // P7: same pattern for nudges-list.
      $('tsc-grade-card').textContent = 'Loading...';
      // Reconciliation reads the already-loaded class payload — render it now (sync).
      renderTscReconcile(_tscCurrentStudentId);
      $('tsc-recent-list').innerHTML = '';
      var unlocksList = $('tsc-unlocks-list');
      if (unlocksList) unlocksList.innerHTML = '';
      var nudgesList = $('tsc-nudges-list');
      if (nudgesList) nudgesList.innerHTML = '';

      drawer.setAttribute('aria-hidden', 'false');
      drawer.classList.add('tsc-open');

      // Fetch grade + recent in parallel. Codex MAJOR fold: allSettled so a
      // failure of one pane doesn't wipe the other's successful payload.
      var base = svcUrl();
      var headers = teacherAuthHeaders();
      var sid = encodeURIComponent(stub.studentId);

      Promise.allSettled([
        fetch(base + '/teacher/student/' + sid + '/grade', { headers: headers }).then(jsonOrErr),
        fetch(base + '/teacher/student/' + sid + '/recent?limit=20', { headers: headers }).then(jsonOrErr),
        fetch(base + '/teacher/student/' + sid + '/lesson-unlocks', { headers: headers }).then(jsonOrErr),
        fetch(base + '/teacher/nudge-history?studentUsername=' + encodeURIComponent(stub.username || '') + '&limit=20', { headers: headers }).then(jsonOrErr)
      ]).then(function(results) {
        // Stale-result guard.
        if (reqId !== _tscReqSeq) return;
        var gradeRes = results[0], recentRes = results[1], unlocksRes = results[2], nudgesRes = results[3];
        if (gradeRes.status === 'fulfilled') {
          renderTscGrade(gradeRes.value);
        } else {
          var gErr = gradeRes.reason;
          $('tsc-grade-card').textContent = 'Error: ' + (gErr && gErr.message ? gErr.message : 'failed');
        }
        if (recentRes.status === 'fulfilled') {
          renderTscRecent(recentRes.value);
        } else {
          $('tsc-recent-list').innerHTML = '<li class="dim">Error loading recent submissions.</li>';
        }
        if (unlocksRes.status === 'fulfilled') {
          renderTscUnlocks(unlocksRes.value);
        } else {
          // unlocks endpoint may 503 if migration not run -- silently render empty state.
          renderTscUnlocks({ ok: false, lessonKeys: [], rows: [] });
        }
        if (nudgesRes.status === 'fulfilled') {
          renderTscNudges(nudgesRes.value);
        } else {
          // nudge-history endpoint may 503 if migration not run -- silently render empty state.
          renderTscNudges({ ok: false, rows: [] });
        }
      });
    }

    function closeTscDrawer() {
      var drawer = $('tsc-drawer');
      if (!drawer) return;
      // Codex MAJOR fold: invalidate any in-flight fetches.
      _tscReqSeq++;
      _tscCurrentStudentStub = null;
      drawer.classList.remove('tsc-open');
      drawer.setAttribute('aria-hidden', 'true');
    }

    // ESC closes the drawer.
    document.addEventListener('keydown', function(e) {
      if (e.key === 'Escape') closeTscDrawer();
    });

    // Overlay-click and close-button click close the drawer.
    document.getElementById('tsc-drawer').addEventListener('click', function(e) {
      if (e.target && e.target.getAttribute('data-tsc-close')) closeTscDrawer();
    });

    // P2: View as student -> open the Desk in a new tab with the impersonation
    // query param. The Desk's _viewAsBootstrap detects the param + hydrates
    // viewAsContext into sessionStorage + reloads as the target student.
    function _openViewAsTab(studentId) {
      if (!studentId) return;
      var url = './ap_stats_roadmap_square_mode.html?viewAsUserId=' + encodeURIComponent(studentId);
      try { window.open(url, '_blank', 'noopener'); } catch (_) {}
    }
    var __viewAsBtn = document.getElementById('tsc-action-view-as');
    if (__viewAsBtn) __viewAsBtn.addEventListener('click', function() {
      _openViewAsTab(_tscCurrentStudentId);
    });

    // T3 (P6 BUILD section 4.2): Render active lesson unlocks in the drawer section.
    function renderTscUnlocks(payload) {
      var el = $('tsc-unlocks-list');
      if (!el) return;
      el.innerHTML = '';
      if (!payload || !payload.ok || !payload.rows || payload.rows.length === 0) {
        el.innerHTML = '<li class="tsc-unlock-empty">No active overrides.</li>';
        return;
      }
      payload.rows.forEach(function (row) {
        var li = document.createElement('li');
        var key = document.createElement('span');
        key.className = 'tsc-unlock-key';
        key.textContent = row.lesson_key;
        var meta = document.createElement('span');
        meta.className = 'tsc-unlock-meta';
        var when = (row.unlocked_at || '').slice(0, 10);
        var by = row.unlocked_by || 'teacher';
        meta.textContent = when + ' \xB7 by ' + by + (row.reason ? ' \xB7 ' + row.reason : '');
        var btn = document.createElement('button');
        btn.type = 'button';
        btn.className = 'tsc-unlock-revoke';
        btn.textContent = 'Revoke';
        btn.addEventListener('click', function () { revokeUnlock(row, li); });
        li.appendChild(key); li.appendChild(meta); li.appendChild(btn);
        el.appendChild(li);
      });
    }

    // T3 (P6 BUILD section 4.2): Revoke a single lesson unlock row.
    async function revokeUnlock(row, liEl) {
      if (!_tscCurrentStudentStub) return;
      // Confirm before destructive op.
      if (!window.confirm('Revoke override for lesson ' + row.lesson_key + '?')) return;
      try {
        var res = await fetch(svcUrl() + '/teacher/lesson-unlock/revoke', {
          method: 'POST',
          headers: Object.assign({ 'Content-Type': 'application/json' }, teacherAuthHeaders()),
          body: JSON.stringify({
            studentUsername: _tscCurrentStudentStub.username,
            lessonKey: row.lesson_key,
          }),
        });
        var j = await res.json().catch(function () { return {}; });
        if (!res.ok || !j.ok) {
          showError('Revoke failed: ' + (j && j.error ? j.error : ('HTTP ' + res.status)));
          return;
        }
        // Optimistic: fade the row out, then remove from DOM.
        liEl.style.opacity = '0.4';
        liEl.style.pointerEvents = 'none';
        setTimeout(function () {
          try { liEl.remove(); } catch (_) {}
          // Codex P6 MINOR fold: if this was the last visible unlock, re-render
          // the empty-state placeholder so the section does not end up blank.
          var listEl = $('tsc-unlocks-list');
          if (listEl && listEl.children.length === 0) {
            listEl.innerHTML = '<li class="tsc-unlock-empty">No active overrides.</li>';
          }
        }, 240);
      } catch (err) {
        showError('Network error revoking: ' + (err && err.message ? err.message : 'unknown'));
      }
    }

    // P7 (TEACHER_STUDENT_CONSOLE_P7_BUILD.md section 3.3): Render nudge history.
    // XSS safety: all text from the row goes through textContent, never innerHTML.
    // Arrow glyphs (>> / <<) are inline ASCII.
    //
    // P12: factored _buildNudgeLi so _loadOlderNudges can reuse the row builder
    // without duplicating the DOM construction. renderTscNudges now also tracks
    // the current offset and controls "Load older" button visibility.
    function _buildNudgeLi(row) {
      var li = document.createElement('li');
      var arrow = document.createElement('span');
      arrow.className = 'tsc-nudge-arrow ' +
        (row.direction === 'teacher' ? 'tsc-nudge-teacher' : 'tsc-nudge-student');
      arrow.textContent = row.direction === 'teacher' ? '>>' : '<<';
      var block = document.createElement('div');
      block.className = 'tsc-nudge-text-block';
      var meta = document.createElement('span');
      meta.className = 'tsc-nudge-meta';
      var when = (row.created_at || '').slice(0, 16).replace('T', ' ');
      var who = row.sender_username || 'unknown';
      meta.textContent = when + ' \xB7 ' + who;
      var text = document.createElement('span');
      text.className = 'tsc-nudge-text';
      text.textContent = row.text || '';
      block.appendChild(meta);
      block.appendChild(text);
      li.appendChild(arrow);
      li.appendChild(block);
      return li;
    }

    function renderTscNudges(payload) {
      var el = $('tsc-nudges-list');
      if (!el) return;
      el.innerHTML = '';
      var olderBtn = $('tsc-nudges-older');
      if (!payload || !payload.ok || !payload.rows || payload.rows.length === 0) {
        el.innerHTML = '<li class="tsc-nudge-empty">No nudges yet.</li>';
        if (olderBtn) olderBtn.style.display = 'none';
        return;
      }
      payload.rows.forEach(function (row) {
        el.appendChild(_buildNudgeLi(row));
      });
      // P12: if this page came back full, more history MIGHT exist.
      _tscNudgeHistoryOffset = payload.rows.length;
      if (olderBtn) {
        olderBtn.style.display = (payload.rows.length >= TSC_NUDGE_PAGE_SIZE) ? '' : 'none';
        olderBtn.disabled = false;
      }
    }

    // ── Teacher chat (Phase 1): compose + send a message via POST /teacher/nudge ──
    // The whole pipeline already exists (persisted; the student sees it in their
    // "Message teacher…" inbox). This wires the previously-disabled Send button:
    // to the open student, or — with "whole class" — to every active PeriodX student.
    function _tscGenNudgeId() {
      return 'n_' + Date.now().toString(36) + '_' + Math.random().toString(36).slice(2, 8);
    }
    function _tscRefreshNudges() {
      var u = _tscNudgeHistoryStudentUsername;
      if (!u) return;
      fetch(svcUrl() + '/teacher/nudge-history?studentUsername=' + encodeURIComponent(u) + '&limit=20', { headers: teacherAuthHeaders() })
        .then(jsonOrErr).then(function (r) { renderTscNudges(r); }).catch(function () {});
    }
    async function _tscClassUsernames() {
      // Broadcast recipients = every active student in the universal PeriodX section
      // (minus the teacher). Public, no-auth — same source the sign-in dial uses.
      try {
        var res = await fetch(svcUrl() + '/roster/section/PeriodX');
        var j = await res.json();
        var list = (j && j.ok && Array.isArray(j.students)) ? j.students : [];
        return list.filter(function (s) { return (s.role || 'student') !== 'teacher'; })
                   .map(function (s) { return s.username; }).filter(Boolean);
      } catch (_) { return []; }
    }
    async function _tscSendNudge() {
      var ta = $('tsc-nudge-text'), statusEl = $('tsc-nudge-status'), sendBtn = $('tsc-nudge-send');
      var broadcast = !!($('tsc-nudge-broadcast') && $('tsc-nudge-broadcast').checked);
      var text = ((ta && ta.value) || '').trim();
      if (statusEl) statusEl.textContent = '';
      if (!text) { if (statusEl) statusEl.textContent = 'Type a message first.'; return; }
      var recipients;
      if (broadcast) {
        recipients = await _tscClassUsernames();
        if (!recipients.length) { if (statusEl) statusEl.textContent = 'Could not load the class list.'; return; }
        if (!window.confirm('Send this message to all ' + recipients.length + ' students?')) { if (statusEl) statusEl.textContent = ''; return; }
      } else {
        if (!_tscNudgeHistoryStudentUsername) { if (statusEl) statusEl.textContent = 'Open a student first, or check "whole class".'; return; }
        recipients = [_tscNudgeHistoryStudentUsername];
      }
      if (sendBtn) sendBtn.disabled = true;
      if (statusEl) statusEl.textContent = 'Sending…';
      var r = await postJson('/teacher/nudge', { nudgeId: _tscGenNudgeId(), recipientUsernames: recipients, text: text }, teacherSecret());
      if (sendBtn) sendBtn.disabled = false;
      if (r.networkError) { if (statusEl) statusEl.textContent = 'Send failed (network).'; return; }
      if (r.status >= 200 && r.status < 300 && r.data && r.data.ok) {
        if (ta) ta.value = '';
        var cnt = $('tsc-nudge-count'); if (cnt) cnt.textContent = '280';
        if (statusEl) statusEl.textContent = broadcast ? ('Sent to ' + recipients.length + ' students.') : 'Sent.';
        if (!broadcast) _tscRefreshNudges();   // refresh the open thread
      } else {
        if (statusEl) statusEl.textContent = (r.data && r.data.error) || ('Send failed (' + r.status + ').');
      }
    }
    (function _wireTscNudgeCompose() {
      var btn = $('tsc-action-nudge');
      if (btn) btn.addEventListener('click', function () {
        var c = $('tsc-nudge-compose');
        if (!c) return;
        c.style.display = (c.style.display === 'none' || !c.style.display) ? 'block' : 'none';
        if (c.style.display === 'block') { var ta = $('tsc-nudge-text'); if (ta) ta.focus(); }
      });
      var sendN = $('tsc-nudge-send'); if (sendN) sendN.addEventListener('click', _tscSendNudge);
      var cancelN = $('tsc-nudge-cancel'); if (cancelN) cancelN.addEventListener('click', function () { var c = $('tsc-nudge-compose'); if (c) c.style.display = 'none'; });
      var taN = $('tsc-nudge-text'); if (taN) taN.addEventListener('input', function () { var cnt = $('tsc-nudge-count'); if (cnt) cnt.textContent = String(280 - (taN.value || '').length); });
    })();

    // P12: async function to fetch and append the next page of nudge history.
    async function _loadOlderNudges() {
      if (!_tscCurrentStudentStub) return;
      if (_tscNudgeHistoryLoading) return;
      // Codex P12 BLOCKER fold: capture the username at click time. After
      // each await the handler re-checks ownership before touching the DOM
      // or the shared pagination state. Without this guard, a fast drawer
      // switch (A -> B) while an older fetch was in flight would pollute
      // B's drawer with A's older rows + corrupt _tscNudgeHistoryOffset.
      var expectedUsername = _tscCurrentStudentStub.username;
      // Sanity precondition: the click should only fire when the drawer
      // is currently on this username (matches the state set by openTscDrawer).
      if (expectedUsername !== _tscNudgeHistoryStudentUsername) return;

      var olderBtn = $('tsc-nudges-older');
      _tscNudgeHistoryLoading = true;
      if (olderBtn) { olderBtn.disabled = true; olderBtn.textContent = 'Loading...'; }

      // Helper: confirm the drawer is STILL on the captured student. Used
      // after each await to abort the rest of the handler on a stale resolve.
      function stillOurDrawer() {
        return !!_tscCurrentStudentStub &&
               _tscCurrentStudentStub.username === expectedUsername &&
               _tscNudgeHistoryStudentUsername === expectedUsername;
      }

      try {
        var headers = teacherAuthHeaders();
        var url = svcUrl() + '/teacher/nudge-history?studentUsername=' +
                  encodeURIComponent(expectedUsername) +
                  '&limit=' + TSC_NUDGE_PAGE_SIZE +
                  '&offset=' + _tscNudgeHistoryOffset;
        var res = await fetch(url, { headers: headers });
        if (!stillOurDrawer()) { _tscNudgeHistoryLoading = false; return; }
        var j = null;
        try { j = await res.json(); } catch (_) {}
        if (!stillOurDrawer()) { _tscNudgeHistoryLoading = false; return; }
        if (!res.ok || !j || !j.ok) {
          // Re-enable + leave button in place so user can retry.
          if (olderBtn) { olderBtn.disabled = false; olderBtn.textContent = 'Load older'; }
          _tscNudgeHistoryLoading = false;
          return;
        }
        var rows = Array.isArray(j.rows) ? j.rows : [];
        var el = $('tsc-nudges-list');
        if (el) { rows.forEach(function (row) { el.appendChild(_buildNudgeLi(row)); }); }
        _tscNudgeHistoryOffset += rows.length;
        if (olderBtn) {
          olderBtn.textContent = 'Load older';
          if (rows.length < TSC_NUDGE_PAGE_SIZE) {
            // No more pages.
            olderBtn.style.display = 'none';
          } else {
            olderBtn.disabled = false;
          }
        }
      } catch (_) {
        if (stillOurDrawer() && olderBtn) {
          olderBtn.disabled = false;
          olderBtn.textContent = 'Load older';
        }
      } finally {
        _tscNudgeHistoryLoading = false;
      }
    }

    // T1 (P6 BUILD section 4.1): Apply Remediation modal handlers.

    function openRemediationModal() {
      var modal = $('tsc-remediation-modal');
      if (!modal || !_tscCurrentStudentStub) return;
      // Populate the header with the student name from the drawer stub.
      $('tsc-remediation-student-name').textContent =
        _tscCurrentStudentStub.realName || _tscCurrentStudentStub.username || 'Student';
      // Reset fields + status.
      $('tsc-rem-unit').value = '';
      $('tsc-rem-skill').value = '';
      $('tsc-rem-notes').value = '';
      var statusEl = $('tsc-remediation-status');
      statusEl.textContent = '';
      statusEl.classList.remove('is-error', 'is-success');
      $('tsc-remediation-confirm').disabled = false;
      modal.classList.add('tsc-modal-open');
      modal.setAttribute('aria-hidden', 'false');
      setTimeout(function () { $('tsc-rem-unit').focus(); }, 30);
    }

    function closeRemediationModal() {
      var modal = $('tsc-remediation-modal');
      if (!modal) return;
      modal.classList.remove('tsc-modal-open');
      modal.setAttribute('aria-hidden', 'true');
    }

    async function submitRemediationProposal() {
      if (!_tscCurrentStudentStub) return;
      var unit = $('tsc-rem-unit').value.trim();
      var skill = $('tsc-rem-skill').value.trim();
      var notes = $('tsc-rem-notes').value.trim();
      var statusEl = $('tsc-remediation-status');
      statusEl.classList.remove('is-error', 'is-success');
      if (!unit) { statusEl.textContent = 'Unit is required.'; statusEl.classList.add('is-error'); return; }
      if (!/^U\d+$/.test(unit)) { statusEl.textContent = 'Unit must look like "U3".'; statusEl.classList.add('is-error'); return; }
      if (!skill) { statusEl.textContent = 'Skill code is required.'; statusEl.classList.add('is-error'); return; }

      var confirmBtn = $('tsc-remediation-confirm');
      confirmBtn.disabled = true;
      statusEl.textContent = 'Submitting...';

      try {
        var res = await fetch(svcUrl() + '/remediation/propose', {
          method: 'POST',
          headers: Object.assign({ 'Content-Type': 'application/json' }, teacherAuthHeaders()),
          body: JSON.stringify({
            studentId: _tscCurrentStudentStub.studentId,
            unit: unit,
            skill: skill,
            notes: notes || undefined,
            proposedBy: 'teacher-dashboard',
          }),
        });
        if (res.status === 503) {
          var j503 = await res.json().catch(function () { return {}; });
          statusEl.textContent = (j503 && j503.error) || 'Remediation table not provisioned (run migration 0004).';
          statusEl.classList.add('is-error');
          confirmBtn.disabled = false;
          return;
        }
        var j = await res.json().catch(function () { return {}; });
        if (!res.ok || !j.ok) {
          statusEl.textContent = (j && j.error) || ('HTTP ' + res.status);
          statusEl.classList.add('is-error');
          confirmBtn.disabled = false;
          return;
        }
        statusEl.textContent = 'Proposed (assignment ' + (j.assignmentId || 'created') + ').';
        statusEl.classList.add('is-success');
        // Auto-close after 1.4 s so the user reads the success line.
        setTimeout(closeRemediationModal, 1400);
      } catch (err) {
        statusEl.textContent = 'Network error: ' + (err && err.message ? err.message : 'unknown');
        statusEl.classList.add('is-error');
        confirmBtn.disabled = false;
      }
    }

    // P12: Wire the "Load older" nudge history button on DOMContentLoaded.
    document.addEventListener('DOMContentLoaded', function () {
      var olderBtn = $('tsc-nudges-older');
      if (olderBtn) olderBtn.addEventListener('click', _loadOlderNudges);
    });

    // Wire the remediation modal button + close affordances on DOMContentLoaded.
    document.addEventListener('DOMContentLoaded', function () {
      var btn = $('tsc-action-remediation');
      if (btn) btn.addEventListener('click', openRemediationModal);
      var confirm = $('tsc-remediation-confirm');
      if (confirm) confirm.addEventListener('click', submitRemediationProposal);
      document.querySelectorAll('#tsc-remediation-modal [data-tsc-modal-close]')
        .forEach(function (el) { el.addEventListener('click', closeRemediationModal); });
      // ESC closes the modal when open. The capture-phase listener fires BEFORE
      // the bubble-phase drawer ESC handler, and stopPropagation prevents the
      // drawer from also closing behind the modal.
      document.addEventListener('keydown', function (e) {
        if (e.key === 'Escape') {
          var modal = $('tsc-remediation-modal');
          if (modal && modal.classList.contains('tsc-modal-open')) {
            e.stopPropagation();
            closeRemediationModal();
          }
        }
      }, true);
    });

    // P9 Wave B: deep-link via URL params (TEACHER_STUDENT_CONSOLE_P9_BUILD.md section 3).
    // ?openDrawerFor=<sid> -> fetch profile + open drawer
    // ?openRemediation=1   -> after drawer opens, click the Apply Remediation button
    document.addEventListener('DOMContentLoaded', function () {
      try {
        var params = new URLSearchParams(window.location.search);
        var deeplinkSid = params.get('openDrawerFor');
        var deeplinkRemediation = params.get('openRemediation') === '1';
        if (!deeplinkSid) return;
        function tryOpen() {
          var headers = teacherAuthHeaders();
          return fetch(svcUrl() + '/teacher/student/' + encodeURIComponent(deeplinkSid) + '/profile', { headers: headers })
            .then(function (res) {
              if (!res.ok) throw new Error('HTTP ' + res.status);
              return res.json();
            })
            .then(function (j) {
              if (!j || !j.ok) throw new Error(j && j.error ? j.error : 'profile load failed');
              openTscDrawer({
                studentId: j.studentId,
                username: j.username,
                realName: j.realName,
                section: j.section,
              });
              if (deeplinkRemediation) {
                // Wait for the drawer animation (220 ms cubic-bezier) + the
                // remediation-button click handler to be wired before firing.
                setTimeout(function () {
                  var btn = $('tsc-action-remediation');
                  if (btn && !btn.disabled) btn.click();
                }, 250);
              }
            })
            .catch(function (err) {
              // If the teacher secret is missing or the profile lookup fails,
              // log and move on. The teacher can enter the secret + re-click
              // the source link to retry. Don't crash the page.
              console.warn('[deeplink] could not open drawer for', deeplinkSid, ':', err && err.message ? err.message : err);
            });
        }
        // Allow the rest of the page (renderSessionStatus etc.) to render first.
        setTimeout(tryOpen, 50);
      } catch (_) {}
    });

    // Render session status on page load (after roster-client.js has run).
    renderSessionStatus();
  


